using System;using System.Collections.Generic;using System.Data;using System.Data.Common;using System.IO;using System.Reflection;using System.Runtime.Serialization;using System.Windows.Forms;
class OrderAddressRegression{
 const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;static Assembly app;static Type repo,model;static int checks;static string address="서울특별시 중구 세종대로 110, 'A'동 #1203";
 static object Field(object o,string n){return o.GetType().GetField(n,F).GetValue(o);}static object Get(object o,string n){return o.GetType().GetProperty(n,F).GetValue(o,null);}static void Set(object o,string n,object v){o.GetType().GetProperty(n,F).SetValue(o,v,null);}static void Put(object o,string n,object v){o.GetType().GetField(n,F).SetValue(o,v);}static object Call(object o,string n,params object[]a){try{return o.GetType().GetMethod(n,F).Invoke(o,a);}catch(TargetInvocationException e){throw e.InnerException;}}static void Check(bool b,string m){if(!b)throw new Exception(m);checks++;}
 static long Save(DbConnection c,DbTransaction t,object order){try{return (long)repo.GetMethod("SaveOrderCore",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{c,t,order});}catch(TargetInvocationException e){throw e.InnerException;}}
 static DataRow Read(DbConnection c,DbTransaction t,long id){using(var q=c.CreateCommand()){q.Transaction=t;q.CommandText=(string)repo.GetField("OrderForEditSql",BindingFlags.Static|BindingFlags.NonPublic).GetRawConstantValue();var p=q.CreateParameter();p.ParameterName="@OrderId";p.Value=id;q.Parameters.Add(p);using(var r=q.ExecuteReader()){var rows=new DataTable();rows.Load(r);return rows.Rows[0];}}}
 static void Ui(string name,DataRow row){var type=app.GetType(name);var o=(Control)FormatterServices.GetUninitializedObject(type);(type.BaseType==typeof(Form)?typeof(Form):typeof(UserControl)).GetConstructor(Type.EmptyTypes).Invoke(o,new object[0]);using(o){Call(o,"InitializeComponent");Call(o,"InitOrderItemTable");Call(o,"InitOrderEditor");Call(o,"InitPreviewEvent");var mode=type.GetField("m_DialogMode",F);mode.SetValue(o,Enum.Parse(mode.FieldType,"New"));Set(Field(o,"tbAddress"),"Text","  "+address+"  ");Check((string)Get(Call(o,"CreateOrderSaveData"),"DeliveryAddress")==address,"UI sends entered address to save model");Call(o,"ApplyLoadedOrder",row);Check((string)Get(Field(o,"tbAddress"),"Text")==Convert.ToString(row["DeliveryAddress"]),"Loaded address visible in "+name);Check((string)Get(Call(o,"CreateOrderSaveData"),"DeliveryAddress")==Convert.ToString(row["DeliveryAddress"]),"Loaded address retained on next save");Call(o,"ResetNewOrder");Check((string)Get(Field(o,"tbAddress"),"Text")=="","New order clears previous address");var legacy=row.Table.Copy();legacy.Columns.Remove("DeliveryAddress");Call(o,"ApplyLoadedOrder",legacy.Rows[0]);Check((string)Get(Field(o,"tbAddress"),"Text")=="","Old row without address loads empty");}}
 [STAThread]static int Main(string[]args){try{Application.EnableVisualStyles();app=Assembly.LoadFrom(Path.GetFullPath(args[0]));Assembly.LoadFrom(Path.GetFullPath(Path.Combine(Path.GetDirectoryName(args[0]),"..","..","dll","MySql.Data.dll")));repo=app.GetType("PineTree.Classes.OrderRepository");model=app.GetType("PineTree.Classes.OrderSaveData");using(var c=(DbConnection)app.GetType("PineTree.Classes.DB").GetMethod("CreateConnection").Invoke(null,null)){c.Open();string cust;using(var q=c.CreateCommand()){q.CommandText="SELECT CustCode FROM Customers ORDER BY CustCode LIMIT 1";cust=Convert.ToString(q.ExecuteScalar());}using(var t=c.BeginTransaction()){try{var order=Activator.CreateInstance(model);Set(order,"CustCode",cust);Set(order,"OrderDate",new DateTime(2099,2,3));Set(order,"OrderTitle","ADDRESS_REGRESSION_"+Guid.NewGuid().ToString("N"));Set(order,"ProductionStatus","신규");Set(order,"SourceChannel","ADDRESS_TEST");Set(order,"Items",Activator.CreateInstance(typeof(List<>).MakeGenericType(app.GetType("PineTree.Classes.OrderItemSaveData"))));Set(order,"DeliveryAddress",address);long id=Save(c,t,order);var row=Read(c,t,id);Check(Convert.ToString(row["DeliveryAddress"])==address,"Korean address with quotes persisted and queried");Ui("PineTree.UserControls.UcOrderDesignPad",row);Ui("PineTree.Dialogs.DialogOrderDesignPad",row);
 Set(order,"OrderId",id);Set(order,"DeliveryAddress","부산광역시 해운대구 센텀대로 1, 2층");Save(c,t,order);Check(Convert.ToString(Read(c,t,id)["DeliveryAddress"])==Get(order,"DeliveryAddress").ToString(),"Address update persisted");Set(order,"DeliveryAddress",null);Save(c,t,order);Check(Convert.ToString(Read(c,t,id)["DeliveryAddress"])=="부산광역시 해운대구 센텀대로 1, 2층","Older editor without address property preserves existing address");Set(order,"DeliveryAddress","");Save(c,t,order);row=Read(c,t,id);Check(row["DeliveryAddress"]==DBNull.Value,"Explicit empty address clears stored value");Ui("PineTree.UserControls.UcOrderDesignPad",row);Ui("PineTree.Dialogs.DialogOrderDesignPad",row);Console.WriteLine("PASS: "+checks+" address save/update/load/clear checks");}finally{t.Rollback();Console.WriteLine("Rolled back temporary address test order");}}}return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
